# frozen_string_literal: true

# The bridge for Tilework.backend = :cpu. Runs Tilework.kernel {} and Buffer
# operators without a GPU and serves as the conformance reference. It cannot
# interpret dialect strings, which it declares as capabilities[:dialect] = false.
#
# A pipeline's "source" is Ruby source generated by backend/cpu/dsl_codegen.rb
# and ops_codegen.rb; eval'ing it yields the Hash
# `{ arg_kinds: [...], proc: lambda { |bufs, scalars, gx,gy,gz, lx,ly,lz,
# bx,by,bz| ... } }`. dispatch uses it to:
#   1. unpack native_args per arg_kinds once for the whole dispatch
#      (unpacking/packing per thread would be needlessly slow).
#   2. loop over grid[i]*block[i] threads in three nested loops, computing the
#      GLOBAL_ID_X / LOCAL_ID_X / GROUP_ID_X equivalents and calling proc.
#   3. after the loop, write buffer arguments back to their bytes once.
require "tilework/backend/cpu/dsl_codegen"
require "tilework/backend/cpu/ops_codegen"

module Tilework
  module CPUBridge
    module_function

    # The CPU has no workgroup/threadgroup size limit, so return a value large
    # enough that Kernel#validate_block! never trips.
    UNLIMITED_THREADS = 2**20

    # offset is for views; always 0 on a real Handle.
    Handle = Struct.new(:data, :freed, :offset)

    def device_name
      "CPU (reference)"
    end

    def device_available?
      true
    end

    # Some nn.rb / ops.rb operations are faster computed directly in Ruby than
    # through a kernel. That is an optimization, not something the capabilities
    # vocabulary (what a backend can do) can express, so the bridge declares it
    # itself instead of core naming the backend (== :cpu).
    def host_fallback?
      true
    end

    # A backend that does not accept dialect kernel strings supplies its own
    # source generators here. ops.rb / dsl.rb call them through Tilework.bridge
    # and never see the name :cpu.
    def ops_codegen
      Tilework::CPU::OpsCodegen
    end

    def dsl_codegen
      Tilework::CPU
    end

    def buffer_alloc(bytesize)
      Handle.new(("\x00" * bytesize).b, false, 0)
    end

    # A view shares the same data with a shifted offset and frees nothing.
    def buffer_view(handle, byte_offset)
      Handle.new(handle.data, false, handle.offset + byte_offset)
    end

    def buffer_write(handle, bytes, offset)
      handle.data[handle.offset + offset, bytes.bytesize] = bytes
      nil
    end

    def buffer_read(handle, bytesize, offset)
      handle.data[handle.offset + offset, bytesize]
    end

    def buffer_free(handle)
      handle.freed = true
      nil
    end

    def pipeline_create(src, _name)
      eval(src) # rubocop:disable Security/Eval -- the source comes from cpu/dsl_codegen.rb / cpu/ops_codegen.rb, not external input
    rescue StandardError, SyntaxError => e
      # Bridge contract: raise compile errors as RuntimeError
      # (Kernel.create_pipeline wraps it in Tilework::CompileError).
      raise RuntimeError, e.message
    end

    def pipeline_max_threads(_pipeline)
      UNLIMITED_THREADS
    end

    def pipeline_free(_pipeline)
      nil
    end

    def dispatch(pipeline, native_args, grid, block, _wait)
      arg_kinds = pipeline.fetch(:arg_kinds)
      bufs = Array.new(arg_kinds.length)
      scalars = Array.new(arg_kinds.length)
      writeback = [] # [[idx, handle, encoder], ...] written back together after the loop

      native_args.each_with_index do |arg, idx|
        kind = arg_kinds[idx]
        # Silently unpacking an unknown dtype as int32 would corrupt values
        # without an error, so only known dtypes pass.
        codec = case kind.to_s
                when /\Afloat32_/  then [->(s) { s.unpack("f*") }, ->(a) { a.pack("f*") }, "f"]
                when /\Aint32_/    then [->(s) { s.unpack("l*") }, ->(a) { a.pack("l*") }, "l"]
                when /\Abfloat16_/ then [BFloat.method(:decode), BFloat.method(:encode), nil]
                else raise Error, "the :cpu backend cannot handle argument kind #{kind.inspect}"
                end
        if kind.end_with?("_buffer")
          # A view sees only what follows its offset. The tail runs past the
          # logical length, but kernel guards never write out of range.
          bufs[idx] = codec[0].call(arg.data.byteslice(arg.offset, arg.data.bytesize - arg.offset))
          writeback << [idx, arg, codec[1]]
        else
          scalars[idx] = arg.unpack1(codec[2])
        end
      end

      total = [grid[0] * block[0], grid[1] * block[1], grid[2] * block[2]]
      proc = pipeline.fetch(:proc)
      (0...total[2]).each do |gz|
        bz = gz / block[2]
        lz = gz % block[2]
        (0...total[1]).each do |gy|
          by = gy / block[1]
          ly = gy % block[1]
          (0...total[0]).each do |gx|
            bx = gx / block[0]
            lx = gx % block[0]
            proc.call(bufs, scalars, gx, gy, gz, lx, ly, lz, bx, by, bz)
          end
        end
      end

      # A view writes back into the middle of the parent's data (replacing the
      # data would detach the String shared with the parent).
      writeback.each do |idx, handle, encoder|
        handle.data[handle.offset, handle.data.bytesize - handle.offset] = encoder.call(bufs[idx])
      end
      nil
    rescue StandardError => e
      # Bridge contract: raise run-time errors as RuntimeError
      # (Kernel#dispatch wraps it in Tilework::LaunchError).
      raise RuntimeError, e.message
    end

    def synchronize
      nil # :cpu dispatch is always synchronous, so there is nothing to do
    end
  end

  register_backend(:cpu, CPUBridge)
end
